// Explicit local-only fixture: synthetic test-pattern MP4 in a disposable class.
const fs=require('node:fs/promises'),path=require('node:path'),esbuild=require('esbuild'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'../..'),dbUrl=new URL(process.env.DATABASE_URL||'http://invalid');
if(!['127.0.0.1','localhost','::1'].includes(dbUrl.hostname)||dbUrl.pathname!='/classin_unified_dev'||process.env.CLASSIN_TEST_OSS!=='1')throw Error('Requires local classin_unified_dev and CLASSIN_TEST_OSS=1');
const output=path.join(root,'outputs/playback-live'),manifestFile=path.join(output,'fixture.json');let api,temp;
(async()=>{
 temp=await fs.mkdtemp(path.join(root,'node_modules/.playback-live-'));const file=path.join(temp,'services.cjs');
 await esbuild.build({stdin:{contents:'export{prisma}from"@/lib/db";export{getCoursewareOssClient}from"@/lib/aliyun-oss";',resolveDir:root},outfile:file,bundle:true,platform:'node',format:'cjs',packages:'external',tsconfig:path.join(root,'tsconfig.json')});api=require(file);const db=api.prisma,oss=api.getCoursewareOssClient();
 if(process.argv.includes('--cleanup')){
  const fixture=JSON.parse(await fs.readFile(manifestFile,'utf8'));
  if(!/^[0-9a-f-]{36}$/.test(fixture.runId)||fixture.objectKey!==`codex-verification/playback/${fixture.runId}/test-pattern.mp4`)throw Error('Invalid fixture scope');
  const course=await db.course.findUnique({where:{id:fixture.courseId},select:{name:true}});
  if(course&&course.name!==`临时回放验收（合成测试图）${fixture.runId}`)throw Error('Fixture class changed; refusing cleanup');
  await oss.delete(fixture.objectKey);try{await oss.head(fixture.objectKey);throw Error('Fixture object remains');}catch(error){if(error.status!==404&&error.code!=='NoSuchKey')throw error;}
  if(course)await db.course.delete({where:{id:fixture.courseId}});
  assert.equal(await db.course.count({where:{id:fixture.courseId}}),0);
  await fs.writeFile(path.join(output,'cleanup.json'),JSON.stringify({cleaned:true,courseId:fixture.courseId,objectDeleted:true},null,2));console.log('PASS disposable class, recording and OSS fixture removed');return;
 }
 try{const old=JSON.parse(await fs.readFile(manifestFile,'utf8'));if(await db.course.count({where:{id:old.courseId}}))throw Error('Existing fixture must be cleaned first');}catch(error){if(error.code!=='ENOENT')throw error;}
 const sourceId=process.env.CLASSIN_PLAYBACK_TEACHER_COURSE_ID;if(!sourceId)throw Error('Set the existing local teacher class ID');
 const source=await db.course.findUniqueOrThrow({where:{id:sourceId},select:{ownerId:true,ownerName:true,teacherId:true,teacherName:true,students:{select:{studentId:true,studentName:true,studentAvatar:true},take:1}}});
 const media=await fs.readFile(path.join(root,'node_modules/.cache/playback-stability/fixture.mp4'));
 if(media.length<1000||media.toString('ascii',4,8)!=='ftyp')throw Error('Requires the synthetic MP4 generated by playback-stability');
 const runId=crypto.randomUUID(),objectKey=`codex-verification/playback/${runId}/test-pattern.mp4`;
 let course;try{
  await oss.put(objectKey,media,{headers:{'Content-Type':'video/mp4','Cache-Control':'private, max-age=300'}});
  course=await db.course.create({data:{name:`临时回放验收（合成测试图）${runId}`,ownerId:source.ownerId,ownerName:source.ownerName,teacherId:source.teacherId,teacherName:source.teacherName,status:'live'}});
  const startedAt=new Date(Date.now()-120000),stoppedAt=new Date(startedAt.getTime()+50000);
  const lesson=await db.courseSession.create({data:{courseId:course.id,position:1,title:'合成测试图回放 · 非真实课堂录像',status:'finished',createdBy:source.ownerId,roomUuid:crypto.randomUUID(),roomType:4,startTime:startedAt,endTime:stoppedAt}});
  if(source.students.length)await db.courseStudent.create({data:{courseId:course.id,...source.students[0]}});
  const recording=await db.classroomRecording.create({data:{courseId:course.id,sessionId:lesson.id,provider:'agora',channelName:'fixture-'+runId,recorderUserId:'fixture',status:'completed',playbackFormat:'mp4',playbackObjectKey:objectKey,startedAt,stoppedAt}});
  await fs.mkdir(output,{recursive:true});const fixture={runId,courseId:course.id,lessonId:lesson.id,recordingId:recording.id,objectKey,mediaBytes:media.length,url:`http://localhost:3000/courses/${course.id}/playback?sessionId=${lesson.id}&lang=en`};await fs.writeFile(manifestFile,JSON.stringify(fixture,null,2));console.log(JSON.stringify({prepared:true,courseId:course.id,lessonId:lesson.id,url:fixture.url,mediaBytes:media.length}));
 }catch(error){if(course)await db.course.delete({where:{id:course.id}});await oss.delete(objectKey);throw error;}
})().finally(async()=>{await api?.prisma.$disconnect();if(temp)await fs.rm(temp,{recursive:true,force:true});}).catch(error=>{console.error(error instanceof Error?error.message:'Fixture failed');process.exitCode=1;});
